SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0800000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 80, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "80", "printedPageNumber": 80, "pdfPageNumber": 463, "sequenceIndex": 70, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0800100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—XII", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0800200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—XIII", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0800000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "promise of liberty,\" Umar bin Abdul Aziz (Rahmatullah alaih) took those dinaars from the slave and deposited them in the Baitul Maal, and advised him to run away to some distant place where he could not be seized.\n\nJust before his death, Muslimah (Rahmatullah alaih) came to him and said, \"Nobody has ever treated his children as you are doing. None of your thirteen sons has anything to live on.\" He sat up in his bed and said, \"I have not held back from my sons what they were entitled to. I have, of course, refused them what was actually due to others. If my sons are righteous, then Allah will surely be their guardian as He has said in His Book: He is the guardian of the righteous (VII: 196)'', but if they are wrong-doers, then why should I care for them?\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800200-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—XII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800300-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Muhammad bin Munkadir (Rahmatullah alaih) was a Hafiz of Hadith. One night, he wept excessively in his Tahajjud. When someone inquired about it, he said, \"During Qiraat, I came across the following words of the Qur''an:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800400-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَبَدَا لَهُمْ سَيِّئَاتُ مَا كَسَبُوا وَحَاقَ بِهِمْ مَا كَانُوا بِهِ يَسْتَهْزِئُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800500-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And the evils that they earned will confront them; and they will be surrounded by what they used to scoff at.\" (XXXIX: 48)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800600-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "He was very anxious and worried at the time of his death, and said that these same words of the Qur''an were looming before him.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800700-0000-4000-8000-000000000001", "structuralNodeId": "b0800200-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—XIII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800800-0000-4000-8000-000000000001", "structuralNodeId": "b0800200-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Thaabit Banaani (Rahmatullah alaih) is another Hafiz of Hadith. He used to cry a great deal while supplicating before Allah. Someone warned him that he would lose his eyesight if he did not stop weeping like that. He replied to him, \"What use are these eyes if these do not weep before Allah.\"\n\nHe used to ask in his prayer, \"O, Allah! Permit me to offer my salaat in my grave, if ever you grant this privilege to any of Thy slaves!\" Abu Sanaan (Rahmatullah alaih) narrates, \"By Allah! I was among those present at the burial of Thaabit Banaani. Just after he had been placed in his grave, one of the bricks from the side fell off. I peeped into the pit to find to my great amazement, that Thaabit was offering", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}]}'::jsonb);